pCount,10,60);ctx.fillText('Depth: '+depth,10,80);}let animationId=null;function start(){if(animationId)cancelAnimationFrame(animationId);function step(){draw();animationId=requestAnimationFrame(step);}step();}function runGenerator(gen){function next(){let res=gen.next();if(res.done){sortedSet=new Set([...Array(barCount).keys()]);pivotIdx=null;rangeStart=null;rangeEnd=null;return;}let act=res.value;processAction(act);if(continuous){setTimeout(next,speed);}else{document.getElementById('nextBtn').disabled=false;}}next();}function processAction(act){compareSet.clear();swapSet.clear();pivotIdx=null;rangeStart=null;rangeEnd=null;switch(act.type){case'compare':compareSet.add(act.i);compareSet.add(act.j);compCount++;break;case'swap':[data[act.i],data[act.j]]=[data[act.j],data[act.i]];swapSet.add(act.i);swapSet.add(act.j);swapCount++;break;case'pivot':pivotIdx=act.i;break;case'range':rangeStart=act.start;rangeEnd=act.end;break;case'sorted':sortedSet.add(act.i);break;case'depth':depth=act.val;if(act.val>maxDepth)maxDepth=act.val;break;}}function* bubbleSort(arr){let n=arr.length;let swapped;do{swapped=false;for(let i=0;i<n-1;i++){yield{type:'compare',i,i+1};if(arr[i]>arr[i+1]){yield{type:'swap',i,i+1};[arr[i],arr[i+1]]=[arr[i+1],arr[i]];swapped=true;}}n--;for(let i=0;i<barCount;i++)if(i>=n)yield{type:'sorted',i};}while(swapped);}function* quickSort(arr,l=0,r=arr.length-1,dep=1){yield{type:'depth',val:dep};if(l<r){let p=yield* partition(arr,l,r,dep);yield{type:'range',start:l,end:r};yield* quickSort(arr,l,p-1,dep+1);yield* quickSort(arr,p+1,r,dep+1);}else if(l===r){yield{type:'sorted',i:l};}}function* partition(arr,l,r,dep){let pivot=arr[r];pivotIdx=r;yield{type:'pivot',i:r};let i=l-1;for(let j=l;j<r;j++){yield{type:'compare',i:j};if(arr[j]<=pivot){i++;yield{type:'swap',i,j};[arr[i],arr[j]]=[arr[j],arr[i]];}}yield{type:'swap',i+1,r};[arr[i+1],arr[r]]=[arr[r],arr[i+1]];yield{type:'sorted',i:i+1};return i+1;}function* mergeSort(arr,l=0,r=arr.length-1,dep=1){yield{type:'depth',val:dep};if(l<r){let m=Math.floor((l+r)/2);yield* mergeSort(arr,l,m,dep+1);yield* mergeSort(arr,m+1,r,dep+1);yield* merge(arr,l,m,r);}else if(l===r){yield{type:'sorted',i:l};}}function* merge(arr,l,m,r){let n1=m-l+1,n2=r-m;let L=arr.slice(l,m+1),R=arr.slice(m+1,r+1);let i=0,j=0,k=l;while(i<n1&&j<n2){yield{type:'compare',i:l+i,j:m+1+j};if(L[i]<=R[j]){arr[k]=L[i];yield{type:'sorted',i:k};i++;}else{arr[k]=R[j];yield{type:'sorted',i:k};j++;}k++;}while(i<n1){arr[k]=L[i];yield{type:'sorted',i:k};i++;k++;}while(j<n2){arr[k]=R[j];yield{type:'sorted',i:k};j++;k++;}}function* heapSort(arr){let n=arr.length;function* heapify(n,i){let largest=i;let l=2*i+1,r=2*i+2;if(l<n){yield{type:'compare',i:l,j:largest};if(arr[l]>arr[largest])largest=l;}if(r<n){yield{type:'compare',i:r,j:largest};if(arr[r]>arr[largest])largest=r;}if(largest!==i){yield{type:'swap',i,i:largest};[arr[i],arr[largest]]=[arr[largest],arr[i]];yield* heapify(n,largest);} }for(let i=Math.floor(n/2)-1;i>=0;i--)yield* heapify(n,i);for(let i=n-1;i>0;i--){yield{type:'swap',i:0,j:i};[arr[0],arr[i]]=[arr[i],arr[0]];yield* heapify(i,0);}for(let i=0;i<n;i++)yield{type:'sorted',i};}function* radixSort(arr){let max=Math.max(...arr);let exp=1;while(Math.floor(max/exp)>0){let output=new Array(arr.length).fill(0);let count=new Array(10).fill(0);for(let i=0;i<arr.length;i++){let digit=Math.floor(arr[i]/exp)%10;count[digit]++;}for(let i=1;i<10;i++)count[i]+=count[i-1];for(let i=arr.length-1;i>=0;i--){let digit=Math.floor(arr[i]/exp)%10;output[count[digit]-1]=arr[i];count[digit]--;}for(let i=0;i<arr.length;i++){if(arr[i]!==output[i]){let j=arr.indexOf(output[i]);yield{type:'swap',i,j};[arr[i],arr[j]]=[arr[j],arr[i]];}}exp*=10;}for(let i=0;i<arr.length;i++)yield{type:'sorted',i};}function createUI(){const container=document.createElement('div');container.style.display='flex';container.style.alignItems='center';container.style.marginTop='10px';const algSelect=document.createElement('select');for(let key in algorithms){let opt=document